import{t as e}from"./api-DOojnsRK.js";var t={getCustomers(){return e.get(`/customers`)},createCustomer(t){return e.post(`/customers`,t)},updateCustomer(t,n){return e.put(`/customers/${t}`,n)},deleteCustomer(t){return e.delete(`/customers/${t}`)},getAllProducts(){return e.get(`/products`)},getProductsByCustomerCode(t){return e.get(`/products`,{params:{customer_code:t}})},getProduct(t){return e.get(`/products/${t}`)},getCustomerProducts(t){return e.get(`/customers/${t}/products`)},createProduct(t){return e.post(`/products`,t)},updateProduct(t,n){return e.put(`/products/${t}`,n)},deleteProduct(t){return e.delete(`/products/${t}`)},getNextSN(t,n){return e.get(`/products/${t}/next-sn`,{params:{yymm:n||void 0}})}};export{t};